mapper.select:
SELECT 
FROM ai_lowcode_publish_task
WHERE tenant_id = #{tenantId}
  AND request_id = #{requestId}
LIMIT 1

mapper.update:
UPDATE ai_lowcode_publish_task
SET task_status = 'DEAD',
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = 'LeaseExpiredAfterRetryLimit',
    update_time = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND task_status = 'PROCESSING'
  AND retry_count >= #{maxRetryCount}
  AND (lock_time IS NULL OR lock_time <= #{staleBefore})

mapper.select:
SELECT 
FROM ai_lowcode_publish_task
WHERE tenant_id = #{tenantId}
  AND id = #{id}
LIMIT 1

mapper.update:
UPDATE ai_lowcode_publish_task
SET task_status = #{status},
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = NULL,
    completed_time = #{now},
    update_by = #{task.operatorId},
    update_time = #{now}
WHERE tenant_id = #{task.tenantId}
  AND id = #{task.id}
  AND task_status = 'PROCESSING'
  AND lock_owner = #{task.lockOwner}

UPDATE ai_lowcode_publish_task
SET task_status = #{status},
    next_retry_time = #{nextRetryTime},
    lock_owner = NULL,
    lock_time = NULL,
    error_type = #{errorType},
    update_by = #{task.operatorId},
    update_time = #{now}
WHERE tenant_id = #{task.tenantId}
  AND id = #{task.id}
  AND task_status = 'PROCESSING'
  AND lock_owner = #{task.lockOwner}

UPDATE ai_lowcode_publish_task
SET current_stage = #{nextStage},
    error_type = NULL,
    update_by = #{task.operatorId},
    update_time = #{now}
WHERE tenant_id = #{task.tenantId}
  AND id = #{task.id}
  AND current_stage = #{expectedStage}
  AND task_status = 'PROCESSING'
  AND lock_owner = #{task.lockOwner}

UPDATE ai_lowcode_publish_task
SET current_stage = #{nextStage},
    task_status = 'PENDING',
    retry_count = 0,
    next_retry_time = NULL,
    lock_owner = NULL,
    lock_time = NULL,
    error_type = NULL,
    update_by = #{task.operatorId},
    update_time = #{now}
WHERE tenant_id = #{task.tenantId}
  AND id = #{task.id}
  AND current_stage = #{expectedStage}
  AND task_status = 'PROCESSING'
  AND lock_owner = #{task.lockOwner}
